let vendorView='guide',vendorEditMode=false,activeVendorProjectId=null,vendorProjectEditMode=false,vendorProjectDraft=null,otherVendorFilter='all',otherVendorSearch='',materialGuides=[],activeMaterialGuideId='',guideEditing=false,guideSeedInFlight=false;
async function ensureMaterialGuideSeed(){if(localTestMode||guideSeedInFlight||materialGuides.length)return;guideSeedInFlight=true;try{const seed=await (await fetch(new URL('assets/material-guide-seed.json',window.__APP_BASE_URL__||location.href))).json();await Promise.all(seed.map(item=>addDoc(collection(db,'materialGuides'),{...item,createdAt:serverTimestamp(),updatedAt:serverTimestamp()})));}catch(error){console.error('material guide seed failed',error);}finally{guideSeedInFlight=false;}}
