function normalizedVendorName(name){return String(name||'').trim().replace(/\s+/g,'').toLowerCase();}
function matchingTradeVendors(name){const key=normalizedVendorName(name);return key?S.tradeVendors.filter(v=>normalizedVendorName(v.companyName)===key):[];}
