window.applyTradeVendorProfileFromCompany=function(){const company=$('tv-company')?.value||'',match=matchingTradeVendors(company)[0];if(match&&normalizedVendorName(company)===normalizedVendorName(match.companyName))chooseTradeVendorProfile(match.id);}
