function renderOtherVendors(){
  const filtered=S.otherVendors.filter(v=>(otherVendorFilter==='all'||(v.categoryIds||[]).includes(otherVendorFilter))&&(!otherVendorSearch||(v.companyName||'').toLowerCase().includes(otherVendorSearch.toLowerCase())));
  return`<div class="vendor-toolbar">${isAdmin()?'<button class="btn btn-p" onclick="showOtherVendorForm()">＋新增其他廠商</button><button class="btn" onclick="showCategoryForm(\'other\')">＋新增類別</button>':''}<select onchange="setOtherVendorFilter(this.value)"><option value="all">全部類別</option>${S.otherVendorCategories.map(c=>`<option value="${c.id}" ${otherVendorFilter===c.id?'selected':''}>${escAttr(c.name)}</option>`).join('')}</select><input type="text" placeholder="搜尋公司名稱" value="${escAttr(otherVendorSearch)}" oninput="setOtherVendorSearch(this.value)"></div><div class="card"><div class="card-hdr"><span class="card-title">其他廠商（${filtered.length}）</span><button class="btn btn-sm" onclick="showOtherCategoryManager()">管理類別</button></div>${filtered.length?filtered.map(renderOtherVendorRow).join(''):'<div class="empty">沒有符合條件的廠商</div>'}</div>`;
}
function renderOtherVendorRow(v){const cats=(v.categoryIds||[]).map(id=>S.otherVendorCategories.find(c=>c.id===id)).filter(Boolean);return`<div class="vendor-row"><div class="vendor-main"><div class="vendor-name">${escAttr(v.companyName||'未命名')}</div><div class="vendor-tags">${cats.length?cats.map(c=>`<span class="vendor-tag">${escAttr(c.name)}</span>`).join(''):'<span class="vendor-tag" style="background:var(--bg);color:var(--text3)">未分類</span>'}</div>${v.note?`<div class="vendor-meta">${escAttr(v.note)}</div>`:''}</div>${isAdmin()?`<div class="vendor-actions"><button class="btn btn-sm" onclick="showOtherVendorForm('${v.id}')">編輯</button><button class="btn btn-sm btn-danger" onclick="deleteOtherVendor('${v.id}')">刪除</button></div>`:''}</div>`;}
window.setOtherVendorFilter=function(v){otherVendorFilter=v;renderVendors();};window.setOtherVendorSearch=function(v){otherVendorSearch=v;renderVendors();const inp=$('panel-vendors')?.querySelector('input[placeholder="搜尋公司名稱"]');if(inp){inp.focus();inp.setSelectionRange(v.length,v.length);}};
window.showOtherVendorForm=function(id){if(!isAdmin())return;const v=id?S.otherVendors.find(x=>x.id===id):null;$('mo-content').innerHTML=`<div class="mo-title">${v?'編輯其他廠商':'新增其他廠商'}</div><div style="margin-top:12px;display:flex;flex-direction:column;gap:8px"><div style="font-size:12px;color:var(--text2)">類別（可複選）</div><div class="vendor-checks">${S.otherVendorCategories.length?S.otherVendorCategories.map(c=>`<label class="vendor-check"><input type="checkbox" name="ov-category" value="${c.id}" ${(v?.categoryIds||[]).includes(c.id)?'checked':''}> ${escAttr(c.name)}</label>`).join(''):'尚無類別，請先新增類別'}</div><input id="ov-company" type="text" placeholder="公司名稱*" value="${escAttr(v?.companyName||'')}"><textarea id="ov-note" rows="4" placeholder="備註">${escAttr(v?.note||'')}</textarea></div><div class="mo-footer"><button class="btn" onclick="closeMo()">取消</button><button class="btn btn-p" onclick="saveOtherVendor(${v?`'${v.id}'`:'null'})">儲存</button></div>`;$('modal').style.display='flex';}
window.saveOtherVendor=async function(id){const companyName=$('ov-company').value.trim();if(!companyName)return alert('請填寫公司名稱');const categoryIds=[...document.querySelectorAll('input[name="ov-category"]:checked')].map(x=>x.value);const data={companyName,categoryIds,note:$('ov-note').value.trim(),updatedAt:new Date().toISOString()};if(id)await updateDoc(doc(db,'otherVendors',id),data);else await addDoc(collection(db,'otherVendors'),{...data,createdAt:new Date().toISOString()});closeMo();renderVendors();}
window.deleteOtherVendor=async function(id){const v=S.otherVendors.find(x=>x.id===id);if(!v||!confirm(`確定刪除「${v.companyName}」？`))return;await deleteDoc(doc(db,'otherVendors',id));renderVendors();}
window.showCategoryForm=function(type){if(!isAdmin())return;$('mo-content').innerHTML=`<div class="mo-title">新增${type==='trade'?'工程項目':'其他廠商類別'}</div><div style="margin-top:12px"><input id="vc-name" type="text" placeholder="類別名稱*" onkeydown="if(event.key==='Enter')saveVendorCategory('${type}')"></div><div class="mo-footer"><button class="btn" onclick="closeMo()">取消</button><button class="btn btn-p" onclick="saveVendorCategory('${type}')">新增</button></div>`;$('modal').style.display='flex';setTimeout(()=>$('vc-name')?.focus(),50);}
window.saveVendorCategory=async function(type){const name=$('vc-name').value.trim(),list=type==='trade'?S.tradeCategories:S.otherVendorCategories,collectionName=type==='trade'?'tradeCategories':'otherVendorCategories';if(!name)return alert('請輸入名稱');if(list.some(x=>x.name===name))return alert('已有相同名稱');const data={name,createdAt:new Date().toISOString()};if(type==='trade')data.sortOrder=sortTradeCategories(list).length;await addDoc(collection(db,collectionName),data);closeMo();renderVendors();}
window.renameVendorCategory=async function(type,id){const list=type==='trade'?S.tradeCategories:S.otherVendorCategories,c=list.find(x=>x.id===id);if(!c)return;const name=prompt('修改類別名稱',c.name)?.trim();if(!name||name===c.name)return;if(list.some(x=>x.id!==id&&x.name===name))return alert('已有相同名稱');await updateDoc(doc(db,type==='trade'?'tradeCategories':'otherVendorCategories',id),{name});renderVendors();}
window.deleteVendorCategory=async function(type,id){const isTrade=type==='trade',list=isTrade?S.tradeCategories:S.otherVendorCategories,c=list.find(x=>x.id===id);if(!c)return;const used=isTrade?S.tradeVendors.filter(v=>v.categoryId===id):S.otherVendors.filter(v=>(v.categoryIds||[]).includes(id));if(used.length)return alert(`「${c.name}」仍有 ${used.length} 家廠商使用，請先移除或改分類後再刪除。`);if(!confirm(`確定刪除類別「${c.name}」？`))return;await deleteDoc(doc(db,isTrade?'tradeCategories':'otherVendorCategories',id));if(!isTrade&&otherVendorFilter===id)otherVendorFilter='all';renderVendors();}
window.showOtherCategoryManager=function(){$('mo-content').innerHTML=`<div class="mo-title">其他廠商類別管理</div><div style="margin-top:12px">${S.otherVendorCategories.map(c=>`<div class="vendor-row" style="padding:8px 0"><div class="vendor-main">${escAttr(c.name)}</div>${isAdmin()?`<button class="btn btn-sm" onclick="closeMo();renameVendorCategory('other','${c.id}')">修改</button><button class="btn btn-sm btn-danger" onclick="closeMo();deleteVendorCategory('other','${c.id}')">刪除</button>`:''}</div>`).join('')||'<div class="empty">尚無類別</div>'}</div><div class="mo-footer">${isAdmin()?'<button class="btn btn-p" onclick="closeMo();showCategoryForm(\'other\')">＋新增類別</button>':''}<button class="btn" onclick="closeMo()">關閉</button></div>`;$('modal').style.display='flex';}
window.openVendorUrl=function(url){const safe=vendorSafeUrl(url);if(safe)window.open(safe,'_blank','noopener');};window.copyVendorUrl=async function(url){try{await navigator.clipboard.writeText(url);alert('網址已複製');}catch(e){prompt('請複製網址',url);}};
window.showVendorQr=function(url,title){const safe=vendorSafeUrl(url);if(!safe)return;const qr='https://quickchart.io/qr?size=300&text='+encodeURIComponent(safe);$('mo-content').innerHTML=`<div class="mo-title">${escAttr(title)}</div><div class="qr-box"><img src="${qr}" alt="LINE 群組 QR Code"><div class="vendor-meta" style="margin-top:8px">掃描後開啟 LINE 群組邀請網址</div></div><div class="mo-footer"><button class="btn" onclick="copyVendorUrl('${escAttr(safe)}')">複製網址</button><button class="btn" onclick="closeMo()">關閉</button></div>`;$('modal').style.display='flex';}
